// One renderer for a person's Green Premium presentation. Lists, profiles, account selectors and
// call surfaces must not each invent their own subset of the entitlement: the server supplies one
// appearance snapshot and this module maps only allowlisted tokens into CSS classes.
if (typeof document !== "undefined") {
  // @ts-expect-error esbuild owns CSS modules in browser bundles; Node tests do not execute this branch.
  void import("./premium_identity.css");
}

import { el } from "../dom.ts";
import type { GreenPremiumAppearance } from "./types.ts";

const NAME_STYLES = new Set([
  "neon-green",
  "gold",
  "gradient-forest",
  "gradient-aurora",
  "pastel-mint",
  "pastel-lilac",
]);
const AVATAR_FRAMES = new Set(["neon-orbit", "falling-leaves", "eco-pulse", "aurora"]);

export function premiumNameClass(premium: GreenPremiumAppearance | null | undefined): string {
  return premium && NAME_STYLES.has(premium.nickname_style)
    ? `gc-premium-name-${premium.nickname_style}`
    : "";
}

export function premiumAvatarFrameClass(premium: GreenPremiumAppearance | null | undefined): string {
  return premium && AVATAR_FRAMES.has(premium.avatar_frame)
    ? `gc-premium-frame-${premium.avatar_frame}`
    : "";
}

export function applyPremiumAvatarFrame(
  target: HTMLElement,
  premium: GreenPremiumAppearance | null | undefined,
): void {
  // Browser elements always expose classList. The guard also keeps the renderer compatible with the
  // intentionally tiny DOM adapters used by server-side rendering and unit tests; an absent classList
  // means there is no visual surface to decorate, not that the identity row should fail to render.
  const classList = (target as HTMLElement & {
    classList?: { add(...tokens: string[]): void; remove(...tokens: string[]): void };
  }).classList;
  if (!classList) return;
  classList.remove("gc-premium-avatar-frame");
  for (const frameName of AVATAR_FRAMES) {
    classList.remove(`gc-premium-frame-${frameName}`);
  }
  const frame = premiumAvatarFrameClass(premium);
  if (frame) classList.add("gc-premium-avatar-frame", frame);
}

export interface PremiumIdentityOptions {
  locale?: string;
  compact?: boolean;
  showStatus?: boolean;
  nameClass?: string;
  badgeClass?: string;
}

export function createPremiumIdentity(
  displayName: string,
  premium: GreenPremiumAppearance | null | undefined,
  options: PremiumIdentityOptions = {},
): HTMLElement {
  const ru = (options.locale ?? "ru").toLowerCase().startsWith("ru");
  const cls = premiumNameClass(premium);
  const name = el("span", {
    class: ["gc-premium-identity-name", options.nameClass ?? "", cls].filter(Boolean).join(" "),
  }, [displayName]);
  const root = el("span", {
    class: `gc-premium-identity${options.compact ? " is-compact" : ""}`,
  }, [name]);
  if (!premium) return root;
  root.append(el("span", {
    class: ["gc-premium-leaf-badge", options.badgeClass ?? ""].filter(Boolean).join(" "),
    title: premium.early_sponsor
      ? (ru ? "Green Premium · Ранний спонсор" : "Green Premium · Early sponsor")
      : "Green Premium",
    "aria-label": "Green Premium",
  }, [premium.early_sponsor ? "🌿✨" : "🌿"]));
  if (options.showStatus !== false && premium.custom_status.trim()) {
    root.append(el("span", { class: "gc-premium-custom-status" }, [premium.custom_status.trim()]));
  }
  return root;
}
